mapper.select:
SELECT DISTRIBUTE_RESERVED_USER AS RESERVER
FROM PROJECT_MASTER
WHERE PRJ_ID = #{prjId}

SELECT T0.OSS_ID , T1.OSS_NAME , T1.OSS_VERSION , T2.CVE_ID , T2.CVSS_SCORE , T2.VULN_SUMMARY , (SELECT GROUP_CONCAT(DISTINCT SUB_T3.PATCH_LINK) FROM NVD_DATA_PATCH_LINK SUB_T3 WHERE SUB_T3.CVE_ID = T0.CVE_ID) AS PATCH_LINK , DATE_FORMAT(T2.MODI_DATE, '%Y-%m-%d') AS MODI_DATE , DATE_FORMAT(T2.PUBL_DATE, '%Y-%m-%d') AS PUBL_DATE FROM OSS_DISCOVERED_SND_EMAIL T0 INNER JOIN OSS_MASTER T1 ON T0.OSS_ID = T1.OSS_ID AND T0.SND_YN = 'N' AND T1.USE_YN = 'Y' LEFT JOIN NVD_CVE_V3 T2 ON T0.CVE_ID = T2.CVE_ID WHERE CONCAT(UPPER(T1.OSS_NAME), '_', T1.OSS_VERSION) IN
#{key}
GROUP BY T0.OSS_ID, T2.CVE_ID ORDER BY T1.OSS_NAME, T1.OSS_VERSION, T2.CVSS_SCORE DESC
